/* うちわ文字プレビュー：素材の質感マッピング（texture.js）
   index.html のメインの <script> の直後に <script src="texture.js"></script> を1行追加するだけで動きます */
(function(){
var ATLAS="data:image/jpeg;base64,";
var IDX={"スパークル": {"ブラック": 0, "ホワイト": 1, "グリーン": 2, "スカイブルー": 3, "ブルー": 4, "パープル": 5, "ラベンダーパープル": 6, "オーロラ": 7, "ゴールド": 8, "シルバー": 9, "マゼンタピンク": 10, "ローズピンク": 11, "ベビーピンク": 12, "ラズベリーピンク": 13, "レッド": 14, "オレンジ": 15, "イエロー": 16, "フレッシュグリーン": 17}, "クリスタル": {"スカイブルー": 18, "ブルー": 19, "パープル": 20, "オーロラ": 21, "ゴールド": 22, "シルバー": 23, "ブラック": 24, "マゼンタピンク": 25, "ラズベリーピンク": 26, "ベビーピンク": 27, "レッド": 28, "オレンジ": 29, "イエロー": 30, "グリーン": 31, "フレッシュグリーン": 32}, "ハート": {"ペールパープル": 33, "オーロラ": 34, "エメラルドグリーン": 35, "フレッシュグリーン": 36, "パステルグリーン": 37, "ゴールド": 38, "シルバー": 39, "ブラック": 40, "パステルイエロー": 41, "ターコイズブルー": 42, "スカイブルー": 43, "パステルブルー": 44, "サファイアブルー": 45, "ブルー": 46, "パープル": 47, "ラベンダーパープル": 48, "マゼンタピンク": 49, "ローズピンク": 50, "ベビーピンク": 51, "チェリーピンク": 52, "レッド": 53, "オレンジ": 54, "イエロー": 55, "レモンイエロー": 56}, "リトルスター": {"オーロラ": 57, "グリーン": 58, "エメラルドグリーン": 59, "フレッシュグリーン": 60, "パステルグリーン": 61, "ゴールド": 62, "シルバー": 63, "ブラック": 64, "パステルイエロー": 65, "スカイブルー": 66, "パステルブルー": 67, "サファイアブルー": 68, "ブルー": 69, "パープル": 70, "ラベンダーパープル": 71, "ペールパープル": 72, "マゼンタピンク": 73, "ローズピンク": 74, "ベビーピンク": 75, "チェリーピンク": 76, "レッド": 77, "オレンジ": 78, "イエロー": 79, "レモンイエロー": 80}, "リトルハート": {"グリーン": 81, "エメラルドグリーン": 82, "ブラウン": 83, "ブラック": 84, "マゼンタピンク": 85, "チェリーピンク": 86, "パープル": 87, "スカイブルー": 88, "オーシャンブルー": 89, "ブルー": 90, "ロイヤルブルー": 91, "メロンソーダ": 92, "シルバー": 93, "ゴールド": 94, "レモンイエロー": 95, "イエロー": 96, "オレンジ": 97, "ビビッドオレンジ": 98, "レッド": 99, "ベビーピンク": 100}};              // 素材 → 色名 → タイル番号
var TW=150,TH=80,COLS=10;     // タイル1枚のサイズと並び
// フォームの素材番号 → 写真の素材
var SETMAP={6:"リトルハート",7:"リトルスター",8:"クリスタル",9:"スパークル"};
var ALIAS={"白":"ホワイト","黒":"ブラック"};
var TEX_SCALE=0.9;            // 質感の模様の大きさ（大きくすると模様が粗くなる）

// リトルハートホログラムの色を、写真どおりの20色に合わせる
COLOR_MAP[6]=["シルバー","ゴールド","レモンイエロー","イエロー","オレンジ","ビビッドオレンジ","レッド","ベビーピンク","マゼンタピンク","チェリーピンク","パープル","スカイブルー","オーシャンブルー","ブルー","ロイヤルブルー","メロンソーダ","グリーン","エメラルドグリーン","ブラウン","ブラック"];
[0,1,2,3].forEach(function(i){if(+$("m"+i).value===6)updateColorSelect(i,true)});

var atlas=new Image(),ready=false,tileCache={};
function tileCanvas(k){
  if(tileCache[k])return tileCache[k];
  // 上下左右に反転コピーして、つなぎ目の出ないタイルにする
  var c=document.createElement("canvas");c.width=TW*2;c.height=TH*2;
  var g=c.getContext("2d"),sx=(k%COLS)*TW,sy=Math.floor(k/COLS)*TH;
  [[1,1,0,0],[-1,1,TW*2,0],[1,-1,0,TH*2],[-1,-1,TW*2,TH*2]].forEach(function(t){
    g.setTransform(t[0],0,0,t[1],t[2],t[3]);g.drawImage(atlas,sx,sy,TW,TH,0,0,TW,TH);
  });
  return tileCache[k]=c;
}
function texFor(slot){
  var m=+$("m"+slot).value,set=IDX[SETMAP[m]];if(!set||!ready)return null;
  var n=$("c"+slot).value;n=ALIAS[n]||n;
  return set[n]!==undefined?set[n]:null;
}

// プレビュー用キャンバスを用意（元の文字spanは隠す）
var pvt=$("pvt"),cv=document.createElement("canvas");
cv.id="pvc";cv.style.cssText="display:block;width:100%;margin:0 auto";
["pvtFill","pvtR1","pvtR2","pvtR3"].forEach(function(id){$(id).style.display="none"});
pvt.appendChild(cv);

var LAYERS=[],W=0,H=0,DPR=1,last=null,t0=performance.now();
var reduce=window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches;

function build(a){
  var txt=a[0],font=a[1],fill=a[2],c1=a[3],c2=a[4],c3=a[5],refl=a[7];
  var fs=parseFloat(getComputedStyle(pvt).fontSize)||35;
  var maxR=c3?8.5:(c2?6:(c1?3:0)),ls=Math.ceil(2*maxR+3),pad=maxR+3;
  DPR=Math.min(window.devicePixelRatio||1,3);W=Math.max(120,pvt.clientWidth);
  var fstr="400 "+fs+"px '"+font+"',sans-serif";
  var mc=document.createElement("canvas").getContext("2d");mc.font=fstr;
  // 1文字ずつ並べて、はみ出したら改行
  var lines=[[]],lw=[0],avail=W-pad*2;
  Array.from(txt).forEach(function(ch){
    var w=mc.measureText(ch).width,L=lines.length-1,add=(lines[L].length?ls:0)+w;
    if(lines[L].length&&lw[L]+add>avail){lines.push([]);lw.push(0);L++;add=w}
    lines[L].push([ch,w]);lw[L]+=add;
  });
  var lh=fs*1.3;H=Math.ceil(lines.length*lh+pad*2);
  cv.width=Math.round(W*DPR);cv.height=Math.round(H*DPR);cv.style.height=H+"px";
  var specs=[[c3,8.5,3,refl.c3],[c2,6,2,refl.c2],[c1,3,1,refl.c1],[fill,0,0,refl.fill]];
  LAYERS=specs.filter(function(s){return s[0]}).map(function(s){
    var c=document.createElement("canvas");c.width=cv.width;c.height=cv.height;
    var g=c.getContext("2d");g.scale(DPR,DPR);g.font=fstr;g.textBaseline="middle";
    g.lineJoin="round";g.lineCap="round";g.lineWidth=s[1]*2;g.fillStyle=g.strokeStyle="#000";
    lines.forEach(function(line,li){
      var x=(W-lw[li])/2,y=pad+lh*(li+.5);
      line.forEach(function(p){if(s[1])g.strokeText(p[0],x,y);g.fillText(p[0],x,y);x+=p[1]+ls});
    });
    g.globalCompositeOperation="source-in";
    var k=texFor(s[2]),paint=s[0];
    if(k!==null){
      paint=g.createPattern(tileCanvas(k),"repeat");
      var sc=fs/80*TEX_SCALE;if(paint.setTransform&&window.DOMMatrix)paint.setTransform(new DOMMatrix([sc,0,0,sc,0,0]));
    }
    g.setTransform(1,0,0,1,0,0);g.fillStyle=paint;g.fillRect(0,0,c.width,c.height);
    if(s[3]){g.globalCompositeOperation="source-atop";g.fillStyle="rgba(255,255,255,.28)";g.fillRect(0,0,c.width,c.height)}
    return {c:c,tex:k!==null,glow:s[3]};
  });
}

var tmp=document.createElement("canvas");
function paint(now){
  var g=cv.getContext("2d");g.setTransform(1,0,0,1,0,0);g.clearRect(0,0,cv.width,cv.height);
  // 光の帯：2.8秒かけて横切り、1.2秒休む
  var cyc=((now-t0)%4000)/2800,show=!reduce&&cyc<=1;
  LAYERS.forEach(function(L){
    if(L.glow){g.shadowColor="rgba(255,255,255,.85)";g.shadowBlur=7*DPR}
    g.drawImage(L.c,0,0);g.shadowBlur=0;g.shadowColor="transparent";
    if(L.tex&&show){
      tmp.width=cv.width;tmp.height=cv.height;var t=tmp.getContext("2d");
      t.drawImage(L.c,0,0);t.globalCompositeOperation="source-atop";
      var bw=cv.width*.3,x=-bw+(cv.width+bw*2)*cyc;
      var gr=t.createLinearGradient(x,0,x+bw,cv.height);
      gr.addColorStop(0,"rgba(255,255,255,0)");gr.addColorStop(.5,"rgba(255,255,255,.55)");gr.addColorStop(1,"rgba(255,255,255,0)");
      t.fillStyle=gr;t.fillRect(0,0,tmp.width,tmp.height);g.drawImage(tmp,0,0);
    }
  });
}
var looping=false;
function animatable(){return !reduce&&!document.hidden&&LAYERS.some(function(L){return L.tex})}
function tick(){paint(performance.now());if(animatable())setTimeout(function(){requestAnimationFrame(tick)},33);else looping=false}
function render(){
  if(!last)return;build(last);paint(performance.now());
  if(!looping&&animatable()){looping=true;setTimeout(function(){requestAnimationFrame(tick)},33)}
}

// 元の描画関数を置き換え（calc() から呼ばれる）
window.styLayers=function(){
  var a=[].slice.call(arguments),key=a[1];last=a;render();
  if(document.fonts&&document.fonts.load){
    document.fonts.load("400 40px '"+key+"'",a[0]).then(function(){if(last===a)render()});
  }
};
atlas.onload=function(){
  ready=true;calc();
  // 素材見本の枠にも実物の質感を表示
  var ph=document.querySelectorAll("#gal .ph"),first={6:"シルバー",7:"オーロラ",8:"オーロラ",9:"シルバー"};
  Object.keys(SETMAP).forEach(function(m){
    var k=IDX[SETMAP[m]][first[m]];if(k===undefined||!ph[m])return;
    var r=document.createElement("canvas");r.width=TW;r.height=TH;r.getContext("2d").drawImage(atlas,(k%COLS)*TW,Math.floor(k/COLS)*TH,TW,TH,0,0,TW,TH);
    ph[m].style.background="url("+r.toDataURL("image/jpeg",.85)+") center/cover";
    ph[m].textContent="";
  });
};
atlas.src=ATLAS;
var rt;window.addEventListener("resize",function(){clearTimeout(rt);rt=setTimeout(render,150)});
document.addEventListener("visibilitychange",function(){if(!document.hidden)render()});
calc();
})();
